import http from "node:http"; import crypto from "node:crypto"; import { EventEmitter } from "node:events";
function frame(text) { const body=Buffer.from(text); const header=body.length<126?Buffer.from([0x81,body.length]):Buffer.from([0x81,126,body.length>>8,body.length&255]); return Buffer.concat([header,body]); }
function decode(buffer) { const length=buffer[1]&127; let offset=2, size=length; if(length===126){size=buffer.readUInt16BE(2);offset=4;} const masked=Boolean(buffer[1]&128); let mask; if(masked){mask=buffer.subarray(offset,offset+4);offset+=4;} const body=Buffer.from(buffer.subarray(offset,offset+size)); if(masked) for(let i=0;i<body.length;i++) body[i]^=mask[i%4]; return body.toString(); }
export async function createFakeChrome() {
  const events=new EventEmitter(); const sockets=new Set(); let page={url:"https://example.test/",title:"Example",text:"Hello Chrome"};
  const server=http.createServer((request,response)=>{ const port=server.address().port; if(request.url==="/json/list") return response.end(JSON.stringify([{id:"page-1",type:"page",title:page.title,url:page.url,webSocketDebuggerUrl:`ws://127.0.0.1:${port}/devtools/page/page-1`}])) ; if(request.url==="/json/version") return response.end(JSON.stringify({webSocketDebuggerUrl:`ws://127.0.0.1:${port}/devtools/browser`})); response.writeHead(404).end(); });
  server.on("upgrade",(request,socket)=>{ const accept=crypto.createHash("sha1").update(request.headers["sec-websocket-key"]+"258EAFA5-E914-47DA-95CA-C5AB0DC85B11").digest("base64"); socket.write(`HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${accept}\r\n\r\n`); sockets.add(socket); socket.on("close",()=>sockets.delete(socket)); socket.on("data",data=>{ if((data[0]&15)===8) return socket.end(); const message=JSON.parse(decode(data)); events.emit("command",message); let result={}; if(message.method==="Runtime.evaluate") result={result:{value:{url:page.url,title:page.title,readyState:"complete",lang:"en",text:page.text}}}; else if(message.method==="Page.captureScreenshot") result={data:Buffer.from("png").toString("base64")}; else if(message.method==="Test.large") result={data:"x".repeat(200)}; else if(message.method==="Test.pending") return; socket.write(frame(JSON.stringify({id:message.id,result}))); }); });
  await new Promise(resolve=>server.listen(0,"127.0.0.1",resolve)); const endpoint=`http://127.0.0.1:${server.address().port}`;
  return { endpoint, navigate(url){page={...page,url}; for(const socket of sockets) socket.write(frame(JSON.stringify({method:"Page.frameNavigated",params:{frame:{url}}})));}, disconnect(){for(const socket of [...sockets]) socket.destroy();}, close(){for(const socket of sockets) socket.destroy(); return new Promise(resolve=>server.close(resolve));}, events };
}
